/* ===== TRIGGER: [dbo].[CO_ContainerProfile].[CO_ContainerProfile_ins] ===== */


CREATE TRIGGER  [CO_ContainerProfile_ins] ON dbo.CO_ContainerProfile FOR INSERT
 AS update CO_ContainerProfile set   ContainerNumber =ContainerNumber1 ,  ContainerLetter =ContainerLetter1 
where  Container=  (select Container from inserted )


GO
/* ===== TRIGGER: [dbo].[CO_ContainerProfile].[CO_ContainerProfile_WebDeleteTrigger] ===== */
CREATE TRIGGER  [dbo].[CO_ContainerProfile_WebDeleteTrigger] ON [dbo].[CO_ContainerProfile] FOR DELETE AS 
begin try 
if system_user<>'SQLWEB\Michaell-admin' and system_user<>'GOLDBOND\SQLWEBUPDATE'
begin
INSERT INTO AuditWeb ( ActionType,  UserName, ActionStatus, Action) SELECT 'DELETE_ CO_ContainerProfile',system_user, 0,' delete [dbo].[CO_ContainerProfile]  Where Container=''' +  isnull(replace(cast(deleted.Container as nvarchar(max)),'''',''''''),'~') + '''' from deleted 
end
end try
begin catch
execute sp_getWebError
end catch
GO
