CREATE TRIGGER  [CO_Containers_Container_del_log] ON [dbo].[CO_Containers]
 FOR DELETE AS

insert  log ( Login_name,  oper, time, table_name, field_name, old_value,       k1, k2, k3, k4, k5)
select     system_user,'DELETE',getdate(),'CO_Containers','*',deleted.[Container],deleted.[Manifest],deleted.[Container],deleted.[DealNumber] ,deleted.[DealNumberSub] , cast(deleted.[EntranceDate] as varchar(50))
from deleted 


GO
