/* ===== TRIGGER: [dbo].[CO_Containers].[CO_Containers_Container_up_log] ===== */

CREATE TRIGGER  [CO_Containers_Container_up_log] ON [dbo].[CO_Containers] FOR UPDATE AS 
insert into log

(  Login_name,  oper, time, table_name, field_name, old_value, new_value, k1, k2, k3
)
 select system_user,'UPDATE',getdate(),'CO_Containers','Container',deleted.[Container],inserted.[Container],inserted.[Manifest],inserted.[Container],inserted.[DealNumber] from inserted,deleted where  (deleted.[Container] <>inserted.[Container]) or  (deleted.[Container] is null and inserted.[Container] is not null)  or  (deleted.[Container] is not null and inserted.[Container] is null)

GO
/* ===== TRIGGER: [dbo].[CO_Containers].[CO_Containers_EntranceDate_up_log] ===== */


CREATE TRIGGER  [dbo].[CO_Containers_EntranceDate_up_log] ON [dbo].[CO_Containers] 
FOR UPDATE 
AS 

if (select   count(*) as counter
    from inserted,deleted 
     where  (deleted.[EntranceDate] <>inserted.[EntranceDate]) or 
     (deleted.[EntranceDate] is null and 
      inserted.[EntranceDate] is not null)  or 
      (deleted.[EntranceDate] is not null and inserted.[EntranceDate] is null))=1

 begin

 
insert  log ( Login_name,  oper, time, table_name, field_name,          old_value,            new_value, k1, k2, k3, k4)
select     system_user,'UPDATE',getdate(),'CO_Containers','EntranceDate',deleted.[EntranceDate],inserted.[EntranceDate],inserted.[Manifest],inserted.[Container],inserted.[DealNumber] ,inserted.[DealNumberSub]
from inserted,deleted where  (deleted.[EntranceDate] <>inserted.[EntranceDate]) or  (deleted.[EntranceDate] is null and inserted.[EntranceDate] is not null)  or  (deleted.[EntranceDate] is not null and inserted.[EntranceDate] is null)

end 

GO
