/* ===== TRIGGER: [dbo].[CO_Containers].[CO_Containers_LocationCode_InsertTrigger] ===== */


CREATE TRIGGER  [dbo].[CO_Containers_LocationCode_InsertTrigger] ON [dbo].[CO_Containers] 
FOR INSERT 
AS 

 
INSERT CO_ContainersLocation (Container, Manifest, Terminal, LocationCode, CreateDate)
SELECT Container, Manifest, Terminal, LocationCode, GETDATE()
FROM inserted
WHERE LocationCode IS NOT NULL 
AND LocationCode <> ''


GO
/* ===== TRIGGER: [dbo].[CO_Containers].[CO_Containers_LocationCode_UpdateTrigger] ===== */


CREATE TRIGGER  [dbo].[CO_Containers_LocationCode_UpdateTrigger] ON [dbo].[CO_Containers] 
FOR UPDATE 
AS 

IF UPDATE (LocationCode) 

BEGIN
	INSERT CO_ContainersLocation (Container, Manifest, Terminal, LocationCode, CreateDate)
	SELECT inserted.Container, inserted.Manifest, inserted.Terminal, inserted.LocationCode, GETDATE()
	FROM inserted
	WHERE inserted.LocationCode IS NOT NULL AND inserted.LocationCode <> ''
	
END




GO
