/* ===== TRIGGER: [dbo].[CP_Deal].[create_RSHNLVFile] ===== */
CREATE TRIGGER [dbo].[create_RSHNLVFile]
ON dbo.CP_Deal 
FOR   UPDATE 
AS
	
	
	 
	 
	 
declare @Permit  char(10)

 
if  ( select len( inserted.permit) FROM  inserted)  =9
 begin

 if         (select  inserted.HandlingTypeCode  FROM  inserted )  =    'HH'   or
          
      (select  inserted.HandlingTypeCode  FROM  inserted )  =    'PP' 


   begin
        --  exec  spRSHNLV    
    select  	@Permit =    (select  inserted.Permit FROM  inserted)
   exec  spRSHNLV    @Permit =@Permit 
 

 end
   
end

GO
