/* ===== TRIGGER: [dbo].[CP_Order].[KerorMoves] ===== */
CREATE TRIGGER [dbo].[KerorMoves]
   ON  [dbo].[CP_Order]
   AFTER  INSERT
AS 
BEGIN
	SET NOCOUNT ON;


		INSERT INTO TB_MessageSms (ContactPersonCell, SmsMessage, ClientCode)
		select (select top (1) configtextvalue from tb_appconfig where configid=4),' יש לנתק חשמל למכולה ' + inserted.[Container] + ' במיקום ' +   inserted.[LocationCode]    ,'998'
		from inserted
		where inserted.container in (SELECT distinct  TB_Location.container FROM dbo.TB_Location 
                    WHERE (select top (1) configtextvalue from tb_appconfig where configid=3) like '%' + substring(TB_Location.LocationCode,1,3) +'%')
					and inserted.worktypecode in (select distinct worktypecode from tb_worktype where forkliftuse=1)
	if @@rowcount > 0
	begin
	select 0
	-- send SMS for all container covering
	end
	
END

