/* ===== TRIGGER: [dbo].[HR_Emp].[Hr_EmpUpdatePinCode] ===== */


CREATE TRIGGER [dbo].[Hr_EmpUpdatePinCode]
   ON  [dbo].[HR_Emp]
   AFTER  INSERT
AS 
BEGIN

	declare @RandomPinCode nvarchar(6)
	declare @Counter int=1

	WHILE @Counter<>0
	BEGIN
		SET @RandomPinCode=(select left(cast(rand()*1000000000+999999 as int),6) as RandomPinCode)
		set @Counter=(SELECT COUNT(*) FROM HR_Emp_Log WHERE UserPinCode LIKE '%' + @RandomPinCode + '%')

	END

	update Hr_Emp set UserPinCode=@RandomPinCode where EmpID=(select EmpID from inserted)
	--select @RandomPinCode

END

GO
