/* ===== TRIGGER: [dbo].[RG_Shifting].[update_location_in_container] ===== */
create  TRIGGER update_location_in_container
   ON  [dbo].[RG_Shifting]
   AFTER INSERT
AS 
BEGIN
UPDATE       CO_Containers
SET                LocationCode = inserted.ToLocation
FROM            CO_Containers CROSS JOIN
                         inserted
WHERE        (CO_Containers.LocationCode = inserted.fromLocation) AND (CO_Containers.Container = inserted.Container)
	 
END

