/* ===== TRIGGER: [dbo].[TB_Location].[TB_Location_Container_up] ===== */
CREATE  TRIGGER  [TB_Location_Container_up] ON  dbo.TB_Location 
FOR UPDATE 
AS 

if (select   count(*) as counter
    from inserted,deleted 
     where  ((deleted.[Container] <>inserted.[Container]) or 
     (deleted.[Container] is null and 
      inserted.[Container] is not null)  or 
      (deleted.[Container] is not null and inserted.[Container] is null)
         ) AND (deleted.[BlocCode] = 'BOND1' OR inserted.[BlocCode] = 'BOND1') AND (deleted.[CHE] = 'GOLD1' OR inserted.[CHE] = 'GOLD1')


         )=1

 begin

     update   dbo.TB_Parameters  set   RefreshMapRTG = 'TRUE'
end


if (select   count(*) as counter
    from inserted,deleted 
     where  ((deleted.[Container] <>inserted.[Container]) or 
     (deleted.[Container] is null and 
      inserted.[Container] is not null)  or 
      (deleted.[Container] is not null and inserted.[Container] is null)
         ) AND (deleted.[BlocCode] = 'BOND2' OR inserted.[BlocCode] = 'BOND2')  AND (deleted.[CHE] = 'GOLD1' OR inserted.[CHE] = 'GOLD1')


         )=1

 begin

     update   dbo.TB_Parameters  set   RefreshMapRTG2 = 'TRUE'
end





if (select   count(*) as counter
    from inserted,deleted 
     where  ((deleted.[Container] <>inserted.[Container]) or 
     (deleted.[Container] is null and 
      inserted.[Container] is not null)  or 
      (deleted.[Container] is not null and inserted.[Container] is null)
         ) AND (deleted.[BlocCode] = 'BOND1' OR inserted.[BlocCode] = 'BOND1') AND (deleted.[CHE] = 'GOLD2' OR inserted.[CHE] = 'GOLD2')


         )=1

 begin

     update   dbo.TB_Parameters  set   RefreshMapRTG3 = 'TRUE'
end


if (select   count(*) as counter
    from inserted,deleted 
     where  ((deleted.[Container] <>inserted.[Container]) or 
     (deleted.[Container] is null and 
      inserted.[Container] is not null)  or 
      (deleted.[Container] is not null and inserted.[Container] is null)
         ) AND (deleted.[BlocCode] = 'BOND2' OR inserted.[BlocCode] = 'BOND2')  AND (deleted.[CHE] = 'GOLD2' OR inserted.[CHE] = 'GOLD2')


         )=1

 begin
 
     update   dbo.TB_Parameters  set   RefreshMapRTG4 = 'TRUE'
end

--select * from dbo.TB_Parameters
if (select   count(*) as counter
    from inserted,deleted 
     where  ((deleted.[Container] <>inserted.[Container]) or 
     (deleted.[Container] is null and 
      inserted.[Container] is not null)  or 
      (deleted.[Container] is not null and inserted.[Container] is null)
         ) AND (deleted.[BlocCode] = 'BOND3' OR inserted.[BlocCode] = 'BOND3')  AND (deleted.[CHE] = 'GOLD3' OR inserted.[CHE] = 'GOLD3')


         )=1

 begin
 
     update   dbo.TB_Parameters  set   RefreshMapRTG3N = 'TRUE'
end

