/* ===== TRIGGER: [dbo].[TC_Client].[SendClientToWMS] ===== */

CREATE TRIGGER [dbo].[SendClientToWMS] on  [dbo].[TC_Client]
   AFTER UPDATE
AS 
BEGIN
	declare @ClientCode char(9) 
	Declare @wms bit
	select @wms = wms,@ClientCode=ClientCode from inserted 
	if @wms=1
	begin
	insert into [dbo].[TC_ClientToWMS] (ClientCode)
			select @ClientCode 
	end 
END

